exercise.referenceSolution:
#include <iostream>
#include <memory>
#include <vector>
#include <utility>
#include <string>

int solve(int a, int b) { auto owner = std::make_shared<int>(a); std::weak_ptr<int> weak = owner; auto held = weak.lock(); owner.reset(); int saved = *held; held.reset(); return weak.lock() ? -9999 : saved + b; }
